<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {api,post,date} from '../api';import ModelsPage from './ModelsPage.vue'
const props=defineProps<{athlete:any}>();const cutoff=ref(new Date().toISOString().slice(0,10)),timezone=ref('Europe/Rome'),experiments=ref<any[]>([]),jobs=ref<any[]>([]),experiment=ref<any>(null),check=ref<any>(null),error=ref(''),busy=ref(false),showResults=ref(false)
const diagnostic=ref<any>(null)
async function openDiagnostic(id:string){try{diagnostic.value=await api('/diagnostics/'+id)}catch(e:any){error.value=e.message}}
let timer:any
async function load(){experiments.value=await api(`/athletes/${props.athlete.id}/experiments`);jobs.value=await api(`/athletes/${props.athlete.id}/jobs`)}
async function open(e:any){error.value='';try{experiment.value=e;check.value=await api(`/experiments/${e.id}/preflight`)}catch(e:any){error.value=e.message}}
async function create(){busy.value=true;error.value='';try{await open(await post(`/athletes/${props.athlete.id}/experiments`,{cutoff:cutoff.value,timezone:timezone.value}));await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function start(){busy.value=true;error.value='';try{await post(`/experiments/${experiment.value.id}/start`,{preflight_hash:check.value.hash,idempotency_key:crypto.randomUUID()});await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(async()=>{try{await load()}catch(e:any){error.value=e.message};timer=setInterval(async()=>{if(jobs.value.some(j=>['queued','running'].includes(j.status)))try{await load()}catch(e:any){error.value=e.message}},2000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><div class="page-heading"><div><p class="eyebrow">TRAIN → VALIDATION</p><h1>Identificazione</h1><p>Stesse strutture congelate. Nuovi parametri solo su tua richiesta.</p></div></div><div class="error" v-if="error">{{error}}</div><form class="card form-grid" @submit.prevent="create"><label>Data di inizio validation<input type="date" v-model="cutoff" required></label><label>Fuso orario<select v-model="timezone"><option>Europe/Rome</option><option>UTC</option></select></label><p>Attività iniziate prima delle 00:00 della data: train. Dalla data compresa: validation. Nessun frazionamento delle attività.</p><button :disabled="busy">Prepara esperimento</button></form><div class="version-list"><button v-for="e in experiments" class="secondary" @click="open(e)">{{date(e.created_at)}} · taglio {{e.cutoff}}</button></div><section v-if="check" class="card"><h2>Prima dell’identificazione</h2><ul><li v-for="s in check.assumptions">{{s}}</li></ul><table><thead><tr><th>Insieme</th><th>Attività</th><th>Tratti P</th><th>Campioni P</th><th>Tratti HR</th><th>Campioni HR previsti / osservati</th></tr></thead><tbody><tr v-for="(c,k) in check.counts"><td>{{k}}</td><td>{{c.activities}}</td><td>{{c.power_segments}}</td><td>{{c.power_samples}}</td><td>{{c.hr_segments}}</td><td>{{c.hr_samples}} / {{c.observed_hr_samples}}</td></tr></tbody></table><p class="error" v-for="reason in check.blocking_reasons">{{reason}}</p><details><summary>Configurazioni, inclusioni ed esclusioni</summary><pre>{{JSON.stringify({config:check.config,counts:check.counts},null,2)}}</pre></details><p class="notice">Questo è l’unico comando che avvia il fitting. Nessuna HR validation viene usata per stimare B o calibrare la previsione.</p><button :disabled="busy||!check.can_start||jobs.some(j=>j.experiment_id===experiment.id&&['queued','running','succeeded'].includes(j.status))" @click="start">Avvia identificazione</button></section><section class="card" v-if="jobs.length"><h2>Elaborazioni</h2><div class="job" v-for="j in jobs"><span class="tag">{{j.status}}</span> {{date(j.created_at)}} · {{j.message}}<p class="error" v-if="j.error">{{j.error}}</p><button v-if="j.diagnostic_id" class="secondary" @click="openDiagnostic(j.diagnostic_id)">Fit e screening del tentativo fallito</button><details><summary>Log</summary><pre>{{j.log?.join('\n')}}</pre></details><button v-if="j.status==='succeeded'" class="secondary" @click="showResults=true">Mostra risultati e versioni</button></div></section><details v-if="diagnostic" class="card" open><summary>Diagnostica del tentativo fallito ? nessun modello pubblicato</summary><pre>{{JSON.stringify(diagnostic,null,2)}}</pre></details><ModelsPage v-if="showResults" :athlete="athlete"/></template>
